import { defineResources, type ResourceSeed } from "./define";

/**
 * Batch 001 deliberately records no verification pass.  The resource fields are
 * compiled from project-controlled sites and repositories; evidence-sensitive
 * facts stay unknown until a later, source-by-source verification pass.
 */
type BatchSeed = Omit<
  ResourceSeed,
  "requiresAccount" | "requiresCreditCard" | "commercialUse" | "personalUse" | "verificationStatus" | "compilationNotes"
>;

function unverified(seed: BatchSeed): ResourceSeed {
  return {
    ...seed,
    requiresAccount: "unknown",
    requiresCreditCard: "unknown",
    commercialUse: "unknown",
    personalUse: "unknown",
    verificationStatus: "UNVERIFIED",
    compilationNotes:
      "Compiled from the project's official site and source repository where available. No verification pass has been recorded.",
  };
}

function openSource(seed: Omit<BatchSeed, "freeStatus" | "openSource">): ResourceSeed {
  return unverified({ ...seed, freeStatus: "OPEN_SOURCE", openSource: true });
}

